(()=>{'use strict';
const $=s=>document.querySelector(s),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
let latest=null,imageBlob=null,imageUrl=null;
let ko={},mine=null,busy=false,active=0,ranking=Array(7).fill(''),dragged=-1;
const units=CoopData.demonsIn('supreme'),name=slug=>{const d=CoopData.DEMON_BY_SLUG.get(slug);return ko[d?.name]||d?.name||slug;};
function portrait(slug){const img=el('img');img.src='/assets/units/'+CoopData.DEMON_BY_SLUG.get(slug).img+'.webp';img.alt=name(slug);img.draggable=false;return img;}
function closePicker(){if($('#vote-picker').open)$('#vote-picker').close();}
function clearDrag(){dragged=-1;for(const card of $('#vote-choices').children)card.className=card.className.replace(/ dragging| drag-over/g,'');}
function moveRank(from,to){if(busy||from===to||from<0||to<0||from>=ranking.length||to>=ranking.length||!ranking[from])return;const selected=ranking[active];const [slug]=ranking.splice(from,1);ranking.splice(to,0,slug);active=selected?ranking.indexOf(selected):to;sync();$('#vote-status').textContent=`${name(slug)}을(를) ${to+1}위로 이동했습니다. 투표 버튼을 눌러 저장해 주세요.`;}
function sync(){const host=$('#vote-choices');host.replaceChildren();ranking.forEach((slug,i)=>{const button=el('button',undefined,'vote-rank-slot'+(active===i?' active':''));button.type='button';button.disabled=busy;button.draggable=!!slug&&!busy;button.ondragstart=e=>{if(busy||!slug){e.preventDefault();return;}dragged=i;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',slug);button.className+=' dragging';};button.ondragover=e=>{if(busy||dragged<0||dragged===i)return;e.preventDefault();e.dataTransfer.dropEffect='move';if(!button.className.includes(' drag-over'))button.className+=' drag-over';};button.ondragleave=()=>{button.className=button.className.replace(' drag-over','');};button.ondrop=e=>{if(busy||dragged<0)return;e.preventDefault();const from=dragged;clearDrag();moveRank(from,i);};button.ondragend=clearDrag;button.setAttribute('aria-label',`${i+1}위 ${slug?name(slug)+' 변경':'초마신 선택'}`);button.setAttribute('aria-pressed',String(active===i));button.append(el('strong',`${i+1}위 · ${7-i}점`));button.append(slug?portrait(slug):el('span','＋','vote-rank-empty'));button.append(el('span',slug?name(slug):'초마신 선택'));button.onclick=()=>{active=i;sync();$('#vote-picker').showModal();};host.append(button);});
const candidates=$('#vote-candidates');candidates.replaceChildren();$('#vote-picker-title').textContent=`${active+1}위 초마신 선택`;
for(const d of [...units].sort((a,b)=>name(a.slug).localeCompare(name(b.slug),'ko'))){const chosen=ranking.indexOf(d.slug),button=el('button',undefined,'vote-candidate');button.type='button';button.disabled=busy||(chosen!==-1&&chosen!==active);button.setAttribute('aria-label',name(d.slug)+(chosen===-1?' 선택':` · ${chosen+1}위 선택됨`));button.append(portrait(d.slug),el('b',name(d.slug)),el('small',chosen===-1?'선택하기':`${chosen+1}위 선택됨`));button.onclick=()=>{ranking[active]=d.slug;closePicker();sync();$('#vote-choices').children[active]?.focus?.();};candidates.append(button);}
$('#vote-submit').disabled=busy||ranking.some(v=>!v)||new Set(ranking).size!==7;$('#vote-refresh').disabled=busy;$('#vote-submit').textContent=mine?'이 순위로 투표 수정하기':'이 순위로 투표하기';}
function render(data){latest=data;$('#vote-image').disabled=false;mine=data.mine;$('#vote-total').textContent=`총 ${data.total.toLocaleString('ko-KR')}표 · 투표를 수정하면 기존 표를 대체합니다.`;const board=$('#dealer-tier-board');board.replaceChildren();if(!data.total)board.append(el('p','아직 투표가 없습니다. 첫 투표를 남겨 주세요.'));for(const tier of [...(data.rows.some(r=>r.tier==='0')?['0']:[]),'S','A','B','C','D','미득표']){const group=data.rows.filter(r=>r.tier===tier),row=el('section',undefined,'dealer-tier-row'+(tier==='0'?' tier-zero':'')),label=el('div',tier==='0'?'0티어':tier,'dealer-tier-label'),cards=el('div',undefined,'dealer-tier-cards');label.style.setProperty('--tier-color',({'0':'#bd913f',S:'#d86f86',A:'#e5a64f',B:'#6e9bd2',C:'#7eae87',D:'#a49baa'})[tier]||'#aaa');for(const r of group){const card=el('article',undefined,'dealer-tier-card');card.append(portrait(r.slug),el('b',name(r.slug)),el('small',r.score+'점 · '+r.votes+'표'));cards.append(card);}if(!group.length)cards.append(el('span','해당 캐릭터 없음','dealer-tier-empty'));row.append(label,cards);board.append(row);}}

async function load(write=false){if(busy)return;busy=true;sync();$('#vote-status').textContent=write?'투표를 저장하는 중…':'결과를 불러오는 중…';try{const response=await fetch('/api/tier-votes',write?{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({ranking})}:{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error||'투표 서버에 연결할 수 없습니다.');render(data);if(mine)ranking=Array.from(mine);$('#vote-status').textContent=write?'투표를 반영했습니다.':mine?'기존 투표를 불러왔습니다. 순서를 바꿔 수정할 수 있습니다.':'좋아하는 캐릭터 7종을 선택해 주세요.';if(write){closePicker();$('#vote-total').textContent+=' 투표를 반영했습니다.';}}catch(error){$('#vote-status').textContent=error.message;}finally{busy=false;sync();}}
$('#vote-picker-close').onclick=closePicker;$('#vote-picker').onclick=e=>{if(e.target===$('#vote-picker')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePicker();}};
$('#tier-ballot').onsubmit=e=>{e.preventDefault();if(!$('#vote-submit').disabled)load(true);};$('#vote-refresh').onclick=()=>load();

async function exportVotes(){if(!latest)return;const button=$('#vote-image');button.disabled=true;$('#vote-image-status').textContent='이미지를 만드는 중…';const data=structuredClone(latest);try{await document.fonts?.ready;const tiers=[...(data.rows.some(r=>r.tier==='0')?['0']:[]),'S','A','B','C','D','미득표'],groups=tiers.map(t=>data.rows.filter(r=>r.tier===t)),heights=groups.map(g=>Math.max(100,Math.ceil(g.length/8)*126+20)),canvas=document.createElement('canvas');canvas.width=1200;canvas.height=180+heights.reduce((a,b)=>a+b,0);const ctx=canvas.getContext('2d');if(!ctx)throw Error('이미지를 만들 수 없습니다.');ctx.fillStyle='#101827';ctx.fillRect(0,0,1200,canvas.height);ctx.fillStyle='#fff';ctx.font='bold 30px sans-serif';ctx.fillText('초마신 투표 티어리스트',28,48);ctx.font='16px sans-serif';ctx.fillStyle='#bec9dd';ctx.fillText('스택 연구소 · 총 '+data.total+'표 · '+new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date()),28,78);ctx.font='14px sans-serif';ctx.fillText('1위가 2위보다 10% 이상 높으면 0티어 · 나머지는 0티어 제외 최고점 기준',28,106);let y=130;for(let i=0;i<tiers.length;i++){const tier=tiers[i],height=heights[i];ctx.fillStyle='#1c283b';ctx.fillRect(28,y,1144,height-6);ctx.fillStyle=({'0':'#bd913f',S:'#d86f86',A:'#e5a64f',B:'#6e9bd2',C:'#7eae87',D:'#a49baa'})[tier]||'#66758b';ctx.fillRect(28,y,100,height-6);ctx.textAlign='center';ctx.fillStyle='#fff';ctx.font='bold 22px sans-serif';ctx.fillText(tier==='0'?'0티어':tier,78,y+50);const images=await Promise.all(groups[i].map(r=>new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>resolve(null);img.src='/assets/units/'+CoopData.DEMON_BY_SLUG.get(r.slug).img+'.webp';})));groups[i].forEach((r,j)=>{const x=140+(j%8)*126,top=y+10+Math.floor(j/8)*126,img=images[j];if(img){const scale=Math.min(68/img.width,68/img.height);ctx.drawImage(img,x+(126-img.width*scale)/2,top,img.width*scale,img.height*scale);}ctx.fillStyle='#fff';ctx.font='14px sans-serif';ctx.fillText(name(r.slug),x+63,top+87,118);ctx.fillStyle='#b9c9dd';ctx.font='12px sans-serif';ctx.fillText(r.score+'점 · '+r.votes+'표',x+63,top+108,118);});if(!groups[i].length){ctx.fillStyle='#aabbd0';ctx.font='16px sans-serif';ctx.fillText('해당 캐릭터 없음',640,y+50);}y+=height;}const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG 생성 실패');if(imageUrl)URL.revokeObjectURL(imageUrl);imageBlob=blob;imageUrl=URL.createObjectURL(blob);$('#vote-preview').src=imageUrl;$('#vote-download').href=imageUrl;$('#vote-image-open').href=imageUrl;let share=false;try{share=!!navigator.canShare?.({files:[new File([blob],'community-tier-list.png',{type:'image/png'})]});}catch{}$('#vote-share').hidden=!share;$('#vote-share-status').textContent='이미지를 길게 눌러 사진에 저장하거나 아래 버튼을 이용하세요.';$('#vote-export').showModal();$('#vote-image-status').textContent='이미지를 만들었습니다.';}catch(error){$('#vote-image-status').textContent='이미지 저장 실패: '+error.message;}finally{button.disabled=false;}}
$('#vote-image').onclick=exportVotes;$('#vote-export-close').onclick=()=>$('#vote-export').close();$('#vote-share').onclick=async()=>{if(!imageBlob)return;try{await navigator.share({files:[new File([imageBlob],'community-tier-list.png',{type:'image/png'})],title:'초마신 투표 티어리스트'});}catch(error){$('#vote-share-status').textContent=error.name==='AbortError'?'공유를 취소했습니다. 파일 저장이나 이미지 길게 누르기를 이용하세요.':'파일 저장이나 이미지 크게 열기를 이용하세요.';}};
fetch('/ko.json').then(r=>r.json()).then(d=>ko=d).catch(()=>{}).finally(()=>{sync();load();});
})();
